package com.metabuild.modules.admin.audit.persistence;
import com.metabuild.admin.api.*;import com.metabuild.shared.kernel.UuidV7Generator;import org.jooq.DSLContext;
public final class JooqAuditEventWriter implements AuditEventWriter {private final DSLContext db;private final UuidV7Generator ids;public JooqAuditEventWriter(DSLContext db,UuidV7Generator ids){this.db=db;this.ids=ids;}public void append(AuditEvent e){db.execute("insert into mb_operation_log(id,actor_id,operation,resource_type,request_method,request_path,success,trace_id,detail) values(?,?,?,?,?,?,?,?,jsonb_build_object('ip',?,'filter',?,'rowCount',?))",ids.generate(),e.actorId(),e.operation(),e.resourceType(),e.requestMethod(),e.requestPath(),e.success(),e.traceId(),e.ip(),e.filterSummary(),e.rowCount());}}
